<script setup>
import { ref, computed, watch, nextTick, onMounted, onBeforeUnmount, defineAsyncComponent } from 'vue'
import { useAuthStore } from './stores/auth'
import { useWorkspaceStore } from './stores/workspace'
import { connectWorkspace, isConfigured, supabase } from './lib/supabase'
import { palette, timeAgo, bytes } from './lib/utils'
import Icon from './components/Icon.vue'
import Modal from './components/Modal.vue'
import AuthScreen from './components/AuthScreen.vue'
import FocusTimer from './components/FocusTimer.vue'
import SpaceList from './components/SpaceList.vue'
const StudyViewer = defineAsyncComponent(() => import('./components/StudyViewer.vue'))
const StudyRoom = defineAsyncComponent(() => import('./components/StudyRoom.vue'))
const RichEditor = defineAsyncComponent(() => import('./components/RichEditor.vue'))
const AdminPanel = defineAsyncComponent(() => import('./components/AdminPanel.vue'))
const ManualDeckDialog = defineAsyncComponent(() => import('./components/ManualDeckDialog.vue'))
import Avatar from './components/Avatar.vue'
import { plainStudyText } from './lib/richText'
import { fileExpiry } from './lib/sourceFiles'
import { peopleInSpace, presenceLabel } from './lib/lounge'
import { startActivityTracking } from './lib/activity'
import { invitationToken } from './lib/appUrl'
const auth = useAuthStore(), workspace = useWorkspaceStore()
const view = ref('workspace'), sidebar = ref(false), filter = ref('all'), search = ref(''), modal = ref(''), selectedAsset = ref(null), peers = ref([]), toast = ref(''), formError = ref(''), busy = ref(false), dragging = ref(false)
const title = ref(''), description = ref(''), color = ref(palette[3]), note = ref(''), inviteRole = ref('viewer'), joinCode = ref(''), inviteLink = ref(''), url = ref(''), key = ref(''), profileName = ref(''), editingFolder = ref(false), deleteId = ref(null)
const profilePhotoFile = ref(null), photoPreview = ref(''), removePhoto = ref(false)
const deleteEmail = ref('')
const noteDrawings = ref([])
const manualDeckOpen = ref(false)
const loungeState = ref('connecting'), inCall = ref(false), now = ref(Date.now())
const mobile = ref(window.innerWidth <= 800)
const fileInput = ref(null), photoInput = ref(null), focusTimer = ref(null); let toastTimeout, expiryClock, bootVersion = 0
let stopActivity, navigationOverflow
const tabs = [{ key: 'all', label: 'All materials' }, { key: 'note', label: 'Reviewers' }, { key: 'deck', label: 'Flashcards' }, { key: 'quiz', label: 'Quizzes' }, { key: 'uploads', label: 'Uploads' }]
const typeLabels = { note: 'Reviewer', deck: 'Flashcards', quiz: 'Practice quiz' }
const typeIcons = { note: 'FileText', deck: 'Layers', quiz: 'CheckCheck' }
const filteredAssets = computed(() => workspace.latestAssets.filter(a => (filter.value === 'all' || a.kind === filter.value) && (a.title + ' ' + plainStudyText(a.content,a.content_format)).toLowerCase().includes(search.value.toLowerCase())))
const groupPeers = computed(() => peopleInSpace(peers.value).filter(p => p.user_id !== auth.user?.id))
const onlineLabel = computed(() => auth.demo ? 'Sample' : !workspace.selectedFolderId ? 'No space' : loungeState.value === 'online' ? presenceLabel(peers.value) : loungeState.value === 'offline' ? 'Offline' : 'Connecting...')
const navigationLabel = computed(() => ({workspace:'My workspace',lounge:'Study lounge',progress:'My progress',admin:'System care'}[view.value]))
function documentExpiry(doc) { return fileExpiry(doc, now.value) }
const greet = computed(() => { const h = new Date().getHours(); return h < 12 ? 'Good morning' : h < 18 ? 'Good afternoon' : 'Good evening' })
function notify(message) { toast.value = message; clearTimeout(toastTimeout); toastTimeout = setTimeout(() => { toast.value = '' }, 5000) }
function openModal(type) {
  sidebar.value = false; formError.value = ''; busy.value = false; modal.value = type
  if (type === 'folder') { editingFolder.value = false; title.value = ''; description.value = ''; color.value = palette[3] }
  if (type === 'note' || type === 'upload') { title.value = ''; note.value = ''; noteDrawings.value = [] }
  if (type === 'share') { inviteLink.value = ''; joinCode.value = ''; inviteRole.value = 'viewer' }
  if (type === 'profile') { profileName.value = auth.profile?.display_name || ''; profilePhotoFile.value = null; removePhoto.value = false; clearPhotoPreview() }
  if (type === 'delete-account') deleteEmail.value = ''
}
function editFolder() { openModal('folder'); editingFolder.value = true; title.value = workspace.selectedFolder.title; description.value = workspace.selectedFolder.description; color.value = workspace.selectedFolder.color }
async function act(fn, success, close = true) { busy.value = true; formError.value = ''; try { await fn(); if (close) modal.value = ''; if (success) notify(success) } catch (e) { formError.value = e.message } finally { busy.value = false } }
async function selectFolder(id) { selectedAsset.value = null; view.value = 'workspace'; search.value = ''; sidebar.value = false; await workspace.selectFolder(id) }
async function upload(file) {
  if (!file) return
  if (auth.demo) { openModal('connect'); return }
  modal.value = ''; formError.value = ''
  try { await workspace.uploadDocument(file); filter.value='all'; notify('Material received. Your reviewer, flashcards, and quiz will appear as they finish. You can keep studying.') }
  catch (e) { notify(e.message) }
  finally { if (fileInput.value) fileInput.value.value = '' }
}
async function finishUpload(doc) {
  try {await workspace.retryDocument(doc);notify('Preparation is queued. Your saved sets are kept.')}
  catch(e){notify(e.message)}
}
function manualDeckCreated(asset) { manualDeckOpen.value=false; selectedAsset.value=asset; filter.value='deck'; notify('Your custom flashcards are saved.') }
async function goToTimer() { view.value='workspace'; await nextTick(); await nextTick(); const timer=focusTimer.value?.$el; timer?.scrollIntoView({ behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center' }); timer?.querySelector('.timer-display')?.focus({preventScroll:true}) }
function chooseFile(event) { void upload(event.target.files?.[0]) }
function drop(event) { dragging.value = false; if (workspace.canEdit) void upload(event.dataTransfer.files[0]) }
async function generatePasted() { if (!note.value.trim()) return; await upload(new File([note.value], `${title.value.trim() || 'Study notes'}.txt`, { type: 'text/plain' })) }
async function copyInvite(mode) { try { await navigator.clipboard.writeText(mode==='code'?invitationToken(inviteLink.value):inviteLink.value); notify(mode==='code'?'Invitation code copied.':'Invitation link copied.') } catch { notify('Select and copy the invitation link.') } }
async function logOut() { try { await focusTimer.value?.finishSession(); await auth.signOut(); modal.value = ''; notify('You’re signed out.') } catch (e) { notify(e.message) } }
function clearPhotoPreview() { if (photoPreview.value) URL.revokeObjectURL(photoPreview.value); photoPreview.value = '' }
function choosePhoto(event) {
  const file = event.target.files?.[0]; event.target.value = ''
  if (!file) return
  if (!['image/jpeg','image/png','image/webp'].includes(file.type) || file.size > 2097152) { formError.value = 'Choose a JPG, PNG, or WebP photo up to 2 MB.'; return }
  clearPhotoPreview(); profilePhotoFile.value = file; photoPreview.value = URL.createObjectURL(file); removePhoto.value = false; formError.value = ''
}
function clearPhoto() { clearPhotoPreview(); profilePhotoFile.value = null; removePhoto.value = true }
async function saveProfile() { await auth.updateProfile(profileName.value,profilePhotoFile.value,removePhoto.value); await workspace.loadFolder() }
async function deleteSpace() { await focusTimer.value?.finishSession(); await workspace.deleteFolder() }
async function deleteAccount() { await focusTimer.value?.finishSession(); await auth.requestAccountDeletion(); selectedAsset.value = null; notify('Deletion scheduled. Sign in within 48 hours to cancel.') }
watch(modal, type => { if (type !== 'profile') clearPhotoPreview() })
watch([() => auth.accountReady, () => auth.user?.id, () => auth.demo, () => auth.recovering, () => auth.maintenanceReady], ([ready,id,demo,recovering,maintenance]) => {
  stopActivity?.(); stopActivity = null
  if (ready && id && !demo && !recovering && maintenance) stopActivity = startActivityTracking({ record:async () => { const result = await supabase.rpc('mark_app_activity'); if (result.error) throw result.error }, onError:() => {} })
})
watch(view, async value => { sidebar.value = false; await nextTick(); const page = {workspace:'workspace-page',lounge:'lounge',progress:'progress-page',admin:'admin-page'}[value]; document.querySelector(`.main-content .${page} .page-title`)?.focus({preventScroll:true}); if (mobile.value) window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth'}) })
watch(() => auth.isAdmin, admin => { if (!admin && view.value === 'admin') view.value = 'workspace' })
function unlockNavigation() { if (navigationOverflow !== undefined) { document.body.style.overflow = navigationOverflow; navigationOverflow = undefined } }
watch([sidebar,mobile], ([open,isMobile]) => { unlockNavigation(); if (open && isMobile) { navigationOverflow = document.body.style.overflow; document.body.style.overflow = 'hidden' } })
function resizeNavigation() { mobile.value = window.innerWidth <= 800; if (!mobile.value) sidebar.value = false }
function closeNavigation(event) { if (event.key === 'Escape' && sidebar.value && !modal.value && !selectedAsset.value) { sidebar.value = false; document.querySelector('.mobile-menu')?.focus() } }
watch(() => auth.accountReady, ready => { if (ready && auth.notice.startsWith('Account deletion cancelled')) notify(auth.notice) })
watch([() => auth.ready, () => auth.user?.id, () => auth.demo, () => auth.recovering, () => auth.accountReady], async ([ready, id, , recovering, accountReady]) => {
  const version = ++bootVersion
  if (!ready || !id || recovering || !accountReady) {
    sidebar.value = false; peers.value = []; selectedAsset.value = null; manualDeckOpen.value=false; view.value = 'workspace'
    if (modal.value !== 'connect') modal.value = ''
    await workspace.dispose(); return
  }
  await workspace.load()
  if (version !== bootVersion) return
  try { await workspace.acceptInvitation(); await workspace.subscribe() } catch (e) { notify(e.message) }
})
watch(() => workspace.selectedFolderId, () => { selectedAsset.value = null; manualDeckOpen.value=false })
onMounted(() => { window.addEventListener('resize',resizeNavigation); window.addEventListener('keydown',closeNavigation); expiryClock = setInterval(() => { now.value = Date.now() }, 60000); auth.initialize().catch(e => { auth.error = e.message; auth.ready = true }) })
onBeforeUnmount(() => { ++bootVersion; stopActivity?.(); unlockNavigation(); window.removeEventListener('resize',resizeNavigation); window.removeEventListener('keydown',closeNavigation); clearTimeout(toastTimeout); clearInterval(expiryClock); clearPhotoPreview(); auth.dispose(); void workspace.dispose() })
</script>
<template>
  <div v-if="!auth.ready || (auth.user && !auth.accountReady && !auth.accountDeletion && !auth.recovering && !auth.error)" class="startup"><img src="/favicon.svg" alt="" /><span>Making a little space…</span></div>
  <AuthScreen v-else-if="!auth.user || auth.recovering || !auth.accountReady" @connect="openModal('connect')" />
  <div v-else class="app-shell">
    <Transition name="shade"><div v-if="sidebar" class="sidebar-shade" @click="sidebar = false"></div></Transition>
    <aside id="main-navigation" class="sidebar" :class="{ 'is-open': sidebar }" :inert="mobile && !sidebar">
      <a class="brand" href="/" @click.prevent="view = 'workspace'"><img src="/favicon.svg" alt="" /><span>synapse<span class="brand-dot">.</span></span></a>
      <span class="brand-subtitle">A calmer way to learn.</span>
      <nav class="main-navigation" aria-label="Main navigation"><button :class="{ active: view === 'workspace' }" @click="view = 'workspace'; sidebar = false"><Icon name="Home" />My workspace</button><button :class="{ active: view === 'lounge' }" @click="view = 'lounge'; sidebar = false"><Icon name="Video" />Study lounge<span v-if="inCall" class="in-call-badge">In call</span><span v-else-if="groupPeers.length" class="nav-count">{{ groupPeers.length }}</span></button><button :class="{ active: view === 'progress' }" @click="view = 'progress'; sidebar = false"><Icon name="Sprout" />My progress</button><button v-if="auth.isAdmin && !auth.demo" :class="{ active: view === 'admin' }" @click="view = 'admin'; sidebar = false"><Icon name="Settings2" />System care</button></nav>
      <div class="sidebar-label"><span>YOUR SPACES</span><button class="icon-button" aria-label="Create study folder" @click="openModal('folder')"><Icon name="Plus" :size="17" /></button></div>
      <SpaceList :spaces="workspace.folders" :selected-id="workspace.selectedFolderId" :user-id="auth.user.id" @select="selectFolder" @create="openModal('folder')" />
      <div class="sidebar-footer"><button v-if="auth.demo" class="preview-banner" @click="openModal('connect')"><span class="status-dot"></span>Sample workspace<Icon name="ArrowUpRight" :size="14" /></button><button class="profile-button" @click="openModal('profile')"><Avatar class="small-avatar" :name="auth.profile?.display_name" :path="auth.profile?.avatar_path" /><span><strong>{{ auth.profile?.display_name || 'Student' }}</strong><small>{{ auth.demo ? 'Preview mode' : 'Your personal workspace' }}</small></span><Icon name="Settings2" :size="17" /></button></div>
    </aside>
    <div class="workspace-shell" :inert="mobile && sidebar"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu" :aria-label="sidebar ? 'Close navigation' : 'Open navigation'" :aria-expanded="sidebar" aria-controls="main-navigation" @click="sidebar = !sidebar"><Icon name="Menu" /></button><span>{{ navigationLabel }}</span><Icon name="ChevronRight" :size="14" /><strong>{{ workspace.selectedFolder?.title || 'A fresh start' }}</strong></div><div class="topbar-right"><button class="icon-button mobile-timer-shortcut" aria-label="Go to focus timer" @click="goToTimer"><Icon name="Clock3" :size="18" /></button><span class="privacy-label"><Icon name="ShieldCheck" :size="15" />{{ workspace.isOwner ? 'Your space, your pace' : 'Shared study space' }}</span><button class="button secondary small" @click="openModal('share')"><Icon name="Users" :size="16" />{{ workspace.selectedFolderId ? 'Invite a friend' : 'Join a space' }}</button></div></header>
      <div v-if="workspace.error" class="workspace-error error-box" role="alert">{{ workspace.error }}<button class="text-button" @click="workspace.load()">Try again</button></div>
      <div class="content-layout" :class="{ 'full-layout': ['lounge','admin'].includes(view) }"><main class="main-content">
        <Transition name="section"><div v-show="view === 'workspace'" class="workspace-page">
          <div class="greeting-row"><span class="eyebrow">{{ greet }}, {{ (auth.profile?.display_name || 'Student').split(' ')[0] }} <span class="greeting-leaf">✳</span></span><span class="tiny muted">{{ new Date().toLocaleDateString(undefined, { weekday: 'long', month: 'short', day: 'numeric' }) }}</span></div>
          <section class="page-heading"><div><h1 class="page-title" tabindex="-1">{{ workspace.selectedFolder?.title || 'Make room for a little clarity.' }}<span class="title-dot">.</span></h1><p>{{ workspace.selectedFolder?.description || 'Start with a subject. Let the ideas come together.' }}</p></div><button v-if="workspace.isOwner" class="icon-button" aria-label="Edit folder details" @click="editFolder"><Icon name="MoreHorizontal" /></button></section>
          <section v-if="workspace.selectedFolderId" class="upload-card" :class="{ dragging, processing: workspace.uploading }" @dragover.prevent="dragging = true" @dragleave.prevent="dragging = false" @drop.prevent="drop"><div class="upload-card-body"><span class="upload-symbol"><Icon :name="workspace.uploading ? 'LoaderCircle' : 'Sparkles'" :size="26" :class="{ spin: workspace.uploading }" /></span><div><h2>{{ workspace.uploading ? 'Completing the ideas…' : 'Bring your notes. Find your clarity.' }}</h2><p>{{ workspace.uploading ? workspace.uploadLabel : 'Turn course materials into reviewers, flashcards, and practice quizzes.' }}</p></div></div><div class="upload-card-bottom"><div class="file-types"><span>PDF</span><span>DOCX</span><span>PPT / PPTX</span><span>IMAGES</span><span class="file-limit">UP TO 20 MB</span></div><button class="button primary" :disabled="!workspace.canEdit || workspace.uploading" @click="openModal('upload')"><Icon name="Plus" :size="17" />{{ workspace.canEdit ? 'Add material' : 'View access' }}</button></div><p class="upload-hint"><Icon name="Clock3" :size="14" /><span>Original files expire after about 24 hours. Saved materials stay; re-upload the original for new sets that need full source detail.</span></p></section>
          <section class="materials"><div class="section-heading materials-heading"><h2>Study materials<span class="muted count">{{ workspace.latestAssets.length }}</span></h2><label class="search-box"><Icon name="Search" :size="16" /><input v-model="search" placeholder="Find a material…" aria-label="Search study materials" /></label></div><div class="material-tabs" role="tablist" aria-label="Material type"><button v-for="tab in tabs" :key="tab.key" role="tab" :aria-selected="filter === tab.key" :class="{ active: filter === tab.key }" @click="filter = tab.key">{{ tab.label }}</button></div>
            <div v-if="workspace.folderGeneration.length" class="generation-list" aria-live="polite"><article v-for="task in workspace.folderGeneration" :key="task.id" class="generation-status" :class="{ paused:task.status==='paused' }"><Icon :name="task.status==='paused' ? 'CirclePause' : 'LoaderCircle'" :class="{ spin:task.status==='processing' }" :size="18" /><div><strong>{{ task.title }}</strong><p>{{ task.message || (task.status==='queued' ? 'In the queue — you can keep studying.' : task.stage==='prepare' ? 'Reading your material…' : `Creating your ${typeLabels[task.stage]?.toLowerCase()}…`) }}</p><div v-if="task.document_id" class="generation-stages"><span v-for="kind in ['note','deck','quiz']" :key="kind" :class="{ done:task.completed_kinds.includes(kind) }"><Icon :name="task.completed_kinds.includes(kind) ? 'Check' : 'Circle'" :size="12" />{{ typeLabels[kind] }}</span></div></div></article></div><p v-if="workspace.generationConnection" class="tiny muted" role="status">{{ workspace.generationConnection }}</p>
            <div v-if="workspace.canEdit && filter === 'deck'" class="manual-deck-entry"><button class="button secondary small" :disabled="workspace.uploading" @click="manualDeckOpen = true"><Icon name="Plus" :size="15" />Create custom flashcards</button><span class="tiny muted">Your own questions. No AI usage.</span></div><div v-if="workspace.loading" class="empty-state"><Icon name="LoaderCircle" class="spin" />Gathering your ideas…</div>
            <div v-else-if="filter === 'uploads'" class="document-list"><div v-for="doc in workspace.folderDocuments" :key="doc.id" class="document-row"><span class="material-icon"><Icon name="FileText" /></span><div><strong>{{ doc.name }}</strong><p class="tiny muted">{{ bytes(doc.size_bytes) }} · {{ doc.status }}</p><p class="expiry-label" :class="{ 'error-text': documentExpiry(doc).expired || documentExpiry(doc).state === 'soon' }"><Icon :name="documentExpiry(doc).expired ? 'TriangleAlert' : 'Clock3'" :size="13" />{{ documentExpiry(doc).label }}</p><p v-if="documentExpiry(doc).expired" class="tiny muted">Saved study materials are kept. Upload the original again for full-detail generation.</p><p v-if="doc.error_message && !workspace.taskForDocument(doc.id)" class="tiny error-text">{{ doc.error_message }}</p></div><button v-if="documentExpiry(doc).expired && workspace.canEdit" class="button secondary small" :disabled="workspace.uploading" @click="openModal('upload')">Upload again</button><button v-else-if="['failed','uploaded','processing'].includes(doc.status) && workspace.canEdit && !workspace.taskForDocument(doc.id)" class="button secondary small" :disabled="workspace.uploading" @click="finishUpload(doc)">Continue preparation</button></div><div v-if="!workspace.folderDocuments.length" class="empty-state"><Icon name="Upload" :size="30" /><h3>No uploads yet.</h3><p>Your uploaded course materials will appear here.</p></div></div>
            <div v-else-if="filteredAssets.length" :key="filter" class="material-grid"><article v-for="asset in filteredAssets" :key="asset.id" class="material-card" :class="'kind-' + asset.kind"><button class="material-open" @click="selectedAsset = asset"><span class="card-top"><span class="material-icon"><Icon :name="typeIcons[asset.kind]" :size="21" /></span><span class="tiny card-kind">{{ typeLabels[asset.kind] }}<span class="set-badge">Set {{ asset.set_number || 1 }}</span></span><Icon name="ArrowUpRight" :size="17" /></span><h3>{{ asset.title }}</h3><p>{{ asset.kind === 'note' ? plainStudyText(asset.content,asset.content_format).slice(0,100) || 'A few ideas, brought into focus.' : asset.kind === 'deck' ? `${asset.data.length} cards to make the connections stick.` : `${asset.data.length} questions. A little check-in with yourself.` }}</p><span class="card-bottom"><span>{{ timeAgo(asset.created_at) }}</span><span>{{ asset.kind === 'note' ? 'Read reviewer' : asset.kind === 'deck' ? 'Start recalling' : 'Try a quiz' }}<Icon name="ArrowRight" :size="14" /></span></span></button><button v-if="workspace.canEdit" class="card-delete icon-button" :aria-label="'Delete ' + asset.title" @click="deleteId = asset.id; openModal('delete')"><Icon name="Trash2" :size="14" /></button></article><button v-if="workspace.canEdit && filter !== 'deck' && filter !== 'quiz'" class="blank-note-card" @click="openModal('note')"><span><Icon name="Plus" :size="23" /></span><strong>A thought of your own?</strong><p>Start a blank note.</p></button></div>
            <div v-else class="empty-state"><Icon name="BookOpen" :size="32" /><h3>{{ search ? 'No connections just yet.' : 'Your next idea starts here.' }}</h3><p>{{ search ? 'Try another search.' : 'Add course material or write your first note.' }}</p><button v-if="!workspace.selectedFolderId" class="button primary" @click="openModal('folder')">Create your first space<Icon name="Plus" :size="16" /></button><button v-else-if="workspace.canEdit" class="button secondary" @click="openModal('note')">Write a note<Icon name="Edit3" :size="16" /></button></div>
            <button v-if="filter === 'uploads' ? workspace.moreDocuments : workspace.moreAssets" class="button secondary load-more" @click="workspace.loadMore(filter === 'uploads' ? 'documents' : 'assets').catch(e => notify(e.message))">Load more materials<Icon name="ChevronDown" :size="16" /></button>
          </section>
        </div></Transition>
        <Transition name="section"><StudyRoom v-if="workspace.selectedFolderId" v-show="view === 'lounge'" @presence="peers = $event" @connection="loungeState = $event" @call="inCall = $event" /></Transition>
        <Transition name="section"><section v-show="view === 'progress'" class="progress-page"><span class="eyebrow">EVERY LITTLE STEP COUNTS</span><h1 class="page-title" tabindex="-1">Look how far you’ve come.</h1><p class="muted">Your lifetime totals across all your study spaces.</p><div class="progress-summary"><div><Icon name="Clock3" :size="25" /><strong>{{ workspace.stats.minutes }}</strong><span>minutes of focus</span></div><div><Icon name="Layers" :size="25" /><strong>{{ workspace.stats.mastered }}</strong><span>cards reviewed 3+ times</span></div><div><Icon name="Flame" :size="25" /><strong>{{ workspace.stats.streak }}</strong><span>day study streak</span></div></div><div class="section-heading"><h2>Your recent practice history</h2><span class="pill">{{ workspace.attempts.length }} completed quizzes</span></div><div v-if="!workspace.attempts.length" class="empty-state"><Icon name="Sprout" :size="36" /><h3>A small start is still a start.</h3><p>Complete a quiz to see your progress here.</p></div><div v-for="attempt in workspace.attempts" :key="attempt.id" class="attempt-row"><span class="material-icon"><Icon name="CheckCheck" /></span><div><strong>{{ workspace.assets.find(a => a.id === attempt.asset_id)?.title || 'Practice quiz' }}</strong><span class="tiny muted">{{ new Date(attempt.created_at).toLocaleString() }}</span></div><span class="attempt-score">{{ Math.round(attempt.correct / attempt.total * 100) }}%<small>{{ attempt.correct }} / {{ attempt.total }}</small></span></div></section></Transition>
        <Transition name="section"><AdminPanel v-if="auth.isAdmin && !auth.demo" v-show="view === 'admin'" :visible="view === 'admin'" @notify="notify" /></Transition>
      </main><aside v-show="!['lounge','admin'].includes(view)" class="right-rail"><section class="together-card"><div class="rail-title"><span><Icon name="Users" />Study group</span><span class="presence-badge"><span class="status-dot" :class="{ online: loungeState === 'online' }"></span>{{ onlineLabel }}</span></div><div class="buddy-avatars"><Avatar :name="auth.profile?.display_name" :path="auth.profile?.avatar_path" /><Avatar v-for="peer in groupPeers.slice(0, 3)" :key="peer.user_id" :name="peer.name" :path="peer.avatar_path" /><button class="avatar add-avatar" aria-label="Invite a study buddy" :disabled="!workspace.selectedFolderId" @click="openModal('share')"><Icon name="Plus" :size="17" /></button></div><p v-if="groupPeers.length">{{ groupPeers.map(p => p.name).slice(0,3).join(', ') }}{{ groupPeers.length > 3 ? ' and ' + (groupPeers.length - 3) + ' more' : '' }}</p><button class="button secondary full" @click="view = 'lounge'" :disabled="!workspace.selectedFolderId"><Icon name="Video" :size="16" />{{ inCall ? 'Return to call' : 'Open study lounge' }}</button></section><FocusTimer ref="focusTimer" :key="auth.user.id + String(auth.demo)" /></aside></div>
    </div>
  </div>
  <StudyViewer v-if="selectedAsset && auth.user && !auth.recovering" :key="selectedAsset.id" :asset="selectedAsset" @close="selectedAsset = null" @notify="notify" @reupload="selectedAsset = null; openModal('upload')" @custom-deck="selectedAsset = null; manualDeckOpen = true" />
  <ManualDeckDialog v-if="manualDeckOpen && auth.user" @close="manualDeckOpen = false" @created="manualDeckCreated" />
  <Modal v-if="modal" :title="modal === 'connect' ? 'Connect your workspace' : modal === 'folder' ? editingFolder ? 'A little change of scenery' : 'Make a new study space' : modal === 'note' ? 'A thought of your own' : modal === 'upload' ? 'Bring your ideas in' : modal === 'share' ? 'Invite your people' : modal === 'profile' ? 'Your little corner' : modal === 'delete-account' ? 'Delete your account?' : modal === 'delete-folder' ? 'Delete this study space?' : 'Delete this set?'" @close="!busy && (modal = '')">
    <p v-if="formError" class="error-box" role="alert">{{ formError }}</p>
    <form v-if="modal === 'connect'" class="stack-form" @submit.prevent="act(() => connectWorkspace(url, key), '')"><p class="muted">Run the included Supabase setup first, then add your public project connection. This browser will open your real workspace.</p><label>Project URL<input v-model="url" type="url" required placeholder="https://YOUR_PROJECT_REF.supabase.co" /></label><label>Publishable key<input v-model="key" required autocomplete="off" placeholder="sb_publishable_…" /></label><p class="tiny muted">Use the publishable key. Keep Gemini keys and secret keys in Supabase only. Connection details are saved on this browser.</p><button class="button primary" :disabled="busy">Connect & reload<Icon name="ArrowRight" :size="17" /></button><button v-if="auth.demo && isConfigured" class="text-button" type="button" @click="auth.leaveDemo(); modal = ''">Back to sign in</button></form>
    <form v-else-if="modal === 'folder'" class="stack-form" @submit.prevent="act(() => editingFolder ? workspace.renameFolder(title.trim(), description.trim(), color) : workspace.createFolder(title.trim(), description.trim(), color), editingFolder ? 'Your space is updated.' : 'Your new study space is ready.')"><p class="muted">A subject, a course, a curiosity. Give it a home.</p><label>Space name<input v-model="title" required maxlength="100" placeholder="e.g. Data Structures" /></label><label>A little description<input v-model="description" maxlength="300" placeholder="What are you exploring?" /></label><label>Choose a color<span class="color-picker"><button v-for="shade in palette" :key="shade" type="button" :aria-label="'Choose color ' + shade" :aria-pressed="color === shade" :style="{ backgroundColor: shade }" :class="{ selected: color === shade }" @click="color = shade"><Icon v-if="color === shade" name="Check" :size="17" /></button></span></label><button class="button primary" :disabled="busy || !title.trim()">{{ busy ? 'Saving…' : editingFolder ? 'Save changes' : 'Create study space' }}<Icon name="ArrowRight" :size="17" /></button><button v-if="editingFolder && workspace.isOwner" type="button" class="button danger small" :disabled="busy || workspace.uploading" @click="openModal('delete-folder')">Delete this space<Icon name="Trash2" :size="15" /></button></form>
    <form v-else-if="modal === 'note'" class="stack-form" @submit.prevent="act(() => workspace.saveNote(title.trim(),note.trim(),null,'html',noteDrawings), 'Your note is saved.')"><label>Give it a title<input v-model="title" required maxlength="150" placeholder="An idea worth keeping…" /></label><RichEditor v-model="note" v-model:annotations="noteDrawings" /><button class="button primary" :disabled="busy || !title.trim() || !plainStudyText(note,'html').trim()">Save note<Icon name="Check" :size="16" /></button></form>
    <div v-else-if="modal === 'upload'" class="stack-form"><button class="upload-modal-zone" @click="fileInput.click()"><Icon name="Upload" :size="31" /><strong>Choose your course material</strong><span>PDF, Word, PowerPoint, images, or plain text</span><small>Up to 20 MB</small></button><div class="source-notice" role="note"><Icon name="Clock3" :size="17" /><div><strong>Original files expire after about 24 hours.</strong><p>Your reviewers, flashcards, and quizzes stay saved. Keep your original and upload it again when generating new sets that need all its details, diagrams, or equations.</p></div></div><div class="output-types"><span><Icon name="FileText" :size="17" />Reviewer</span><span><Icon name="Layers" :size="17" />Flashcards</span><span><Icon name="CheckCheck" :size="17" />Practice quiz</span></div><details class="paste-details"><summary>Or paste your notes</summary><label>Title<input v-model="title" maxlength="100" placeholder="Chapter or topic" /></label><textarea v-model="note" rows="7" maxlength="100000" placeholder="Paste at least 20 characters of source notes…"></textarea><button class="button primary" :disabled="note.trim().length < 20" @click="generatePasted">Generate</button></details><button class="text-button" @click="openModal('note')">Write a blank note</button></div>
    <div v-else-if="modal === 'share'" class="stack-form"><form class="join-space-form stack-form" @submit.prevent="act(async () => { await workspace.acceptInvitation(joinCode); view = 'workspace' }, 'You joined the shared space.')"><label>Join a shared space<input v-model="joinCode" type="text" autocomplete="off" maxlength="2000" placeholder="Paste an invitation link or code…" aria-label="Invitation link or code" :disabled="busy" /></label><button class="button secondary" :disabled="busy || !joinCode.trim()">{{ busy ? 'Joining…' : 'Join space' }}<Icon name="ArrowRight" :size="16" /></button></form><p class="muted">{{ workspace.isOwner ? 'Create a link to invite someone below.' : workspace.selectedFolderId ? 'The space owner can create invitation links.' : 'Paste an invitation to get started.' }}</p><template v-if="workspace.isOwner"><label>They can<select v-model="inviteRole"><option value="viewer">View and study</option><option value="editor">Add and edit materials</option></select></label><button class="button primary" :disabled="busy" @click="act(async () => { inviteLink = await workspace.createInvitation(inviteRole) }, '', false)">Create invitation<Icon name="Link" :size="16" /></button><div v-if="inviteLink" class="invite-result"><input :value="inviteLink" readonly aria-label="Invitation link" @focus="$event.target.select()" /><button class="icon-button" aria-label="Copy invitation link" @click="copyInvite"><Icon name="Copy" :size="17" /></button><button class="text-button invitation-code-button" @click="copyInvite('code')">Copy invitation code</button><p class="tiny muted">Single use. Expires in 7 days. Send this link to your friend.</p></div></template><div v-if="workspace.members.length" class="member-list"><h3>People in this space</h3><div v-for="member in workspace.members" :key="member.user_id" class="person-row"><Avatar class="small-avatar" :name="member.profiles?.display_name" :path="member.profiles?.avatar_path" /><div><strong>{{ member.profiles?.display_name || 'Study buddy' }}</strong><span class="tiny muted">{{ member.role }}</span></div><select v-if="workspace.isOwner" :value="member.role" :aria-label="'Role for ' + member.profiles?.display_name" @change="workspace.updateMember(member.user_id, $event.target.value === 'remove' ? null : $event.target.value).catch(e => { formError = e.message })"><option value="viewer">Viewer</option><option value="editor">Editor</option><option value="remove">Remove</option></select></div></div></div>
    <div v-else-if="modal === 'profile'" class="stack-form"><div class="profile-photo-editor"><img v-if="photoPreview" :src="photoPreview" alt="New profile photo" class="profile-photo-preview" /><Avatar v-else class="profile-photo-preview" :name="profileName" :path="removePhoto ? null : auth.profile?.avatar_path" /><div><button class="button secondary small" :disabled="busy" @click="photoInput.click()"><Icon name="Upload" :size="15" />{{ auth.profile?.avatar_path || photoPreview ? 'Change photo' : 'Add photo' }}</button><button v-if="auth.profile?.avatar_path || photoPreview" class="text-button" :disabled="busy" @click="clearPhoto">Remove photo</button><p class="tiny muted">JPG, PNG, or WebP · Up to 2 MB</p></div></div><label>Your name<input v-model="profileName" maxlength="80" /></label><p class="tiny muted">{{ auth.demo ? 'You’re exploring sample data saved on this browser.' : auth.user.email }}</p><button class="button primary" :disabled="busy || !profileName.trim()" @click="act(saveProfile,'Your profile is updated.')">{{ busy ? 'Saving…' : 'Save profile' }}<Icon name="Check" :size="16" /></button><button class="button secondary" :disabled="busy" @click="logOut"><Icon name="LogOut" :size="16" />{{ auth.demo ? 'Exit sample workspace' : 'Sign out' }}</button><details class="account-retention-info"><summary>Account retention</summary><p>Accounts unused for at least 90 days may be reviewed for cleanup by the app owner. A scheduled inactive-account removal has a 7-day recovery window: return to Synapse or sign in before the deadline to cancel. Accounts whose materials are in a space used by another person in the last 30 days are protected.</p></details><div class="profile-danger"><button class="text-button danger-text" :disabled="busy || auth.demo || auth.isAdmin" @click="openModal('delete-account')"><Icon name="Trash2" :size="15" />Delete account</button><p class="tiny muted">{{ auth.isAdmin ? 'Admin accounts are protected. Transfer the role in Supabase before deleting this account.' : auth.demo ? 'Account deletion is available when signed in to a real account.' : 'A 48-hour period lets you cancel by signing back in.' }}</p></div></div>
    <form v-else-if="modal === 'delete-account'" class="stack-form" @submit.prevent="act(deleteAccount,'',true)"><p class="muted">We will schedule deletion and sign you out. Sign in again within <strong>48 hours</strong> to cancel and keep your data.</p><p class="muted">After that period, cleanup permanently removes your account, profile photos, uploads, study materials, messages, and progress. Your owned spaces and their contents are removed for everyone. Materials you created or uploaded in other shared spaces are also removed.</p><p class="tiny muted">Owned spaces are unavailable while deletion is pending. Cleanup runs on a schedule, so final removal happens on a run after the 48-hour deadline.</p><label>Type your email to confirm<input v-model="deleteEmail" type="email" required autocomplete="off" :placeholder="auth.user?.email" /></label><div class="inline-actions"><button type="button" class="button secondary" :disabled="busy" @click="modal = 'profile'">Keep account</button><button class="button danger" :disabled="busy || auth.demo || deleteEmail.trim().toLowerCase() !== auth.user?.email?.toLowerCase()">{{ busy ? 'Scheduling…' : 'Schedule account deletion' }}</button></div></form>
    <div v-else-if="modal === 'delete-folder'" class="stack-form"><p>Delete <strong>{{ workspace.selectedFolder?.title }}</strong> and all its materials, saved sets, practice progress, messages, and invitations for everyone in this space?</p><p class="error-text tiny">This cannot be undone.</p><button class="button danger" :disabled="busy || workspace.uploading" @click="act(deleteSpace,'The study space is deleted.')">{{ busy ? 'Deleting…' : 'Delete space and its materials' }}<Icon name="Trash2" :size="16" /></button><button class="button secondary" :disabled="busy" @click="modal = ''">Keep this space</button></div>
    <div v-else class="stack-form"><p>This removes this set and its saved practice progress. Other sets remain. The original upload stays until its scheduled expiry.</p><button class="button danger" :disabled="busy" @click="act(() => workspace.deleteAsset(deleteId), 'The material is deleted.')">Delete this set<Icon name="Trash2" :size="16" /></button><button class="button secondary" @click="modal = ''">Keep it</button></div>
  </Modal>
  <input ref="fileInput" type="file" hidden accept=".pdf,.docx,.pptx,.ppt,.jpg,.jpeg,.png,.webp,.txt,.md" @change="chooseFile" />
  <input ref="photoInput" type="file" hidden accept="image/jpeg,image/png,image/webp" @change="choosePhoto" />
  <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Icon name="Check" :size="17" /><span>{{ toast }}</span><button class="icon-button" aria-label="Dismiss message" @click="toast = ''"><Icon name="X" :size="15" /></button></div></Transition>
</template>
